export const INTELLIGENCE_SPECIFIC_CATALOG_WORKFLOW_COUNT = Object.keys(INTELLIGENCE_SPECIFIC_WORKFLOWS).length;
export const hasIntelligenceSpecificCatalogWorkflow = (name: string): boolean => Boolean(INTELLIGENCE_SPECIFIC_WORKFLOWS[name]);
